        title: "Update software",
        description: "Update all office computers with the latest security patches and software updates.",
        done: true,
        dueDate: "2024-06-10",
        createdAt: new Date().toISOString()
    }
];
//---

app.get('/tasks', (req, res) => {
    if (!isAuthenticated(req)) {
        return res.status(401).send('user is not authenticated')
    }

    res.json(tasks)
});

app.post('/tasks', (req, res) => {
    if (!isAuthenticated(req)) {
        return res.status(401).send('user is not authenticated')
    }

    if (isTaskStructureCorrect(req, res)) {
        const { title, description, done, dueDate } = req.body

        const nextId = tasks.reduce((maxId, task) => Math.max(maxId, task.id), 0) + 1

        const newTask = { id: nextId, title, description, done, dueDate, createdAt: new Date() }
        tasks.push(newTask);
        res.status(201).send(`task ${title} created`)
    }
});

app.get('/tasks/:id', (req, res) => {
    if (!isAuthenticated(req)) {
        return res.status(401).send('user is not authenticated')
    }

    const task = tasks.find(t => t.id === parseInt(req.params.id))
    if (task) {
        res.json(task)
    } else {
        res.status(404).send('task not found')
    }
});

app.patch('/tasks/:id', (req, res) => {
    if (!isAuthenticated(req)) {
        return res.status(401).send('user is not authenticated')
    }

    let task = tasks.find(t => t.id === parseInt(req.params.id))
    if (!task) {
        return res.status(404).send('task not found')
    }

    //--- Assisted with basic coding tools
    const { title, description, done, dueDate } = req.body
    task.title = title || task.title
    task.description = description || task.description
    task.done = done !== undefined ? done : task.done
    task.dueDate = dueDate || task.dueDate
    res.json(task)
    //---
});

app.delete('/tasks/:id', (req, res) => {
    if (!isAuthenticated(req)) {
        return res.status(401).send('user is not authenticated')
    }

    const index = tasks.findIndex(t => t.id === parseInt(req.params.id))
    //--- Assisted with basic coding tools
    if (index === -1) {
        return res.status(404).send('task not found')
    }
    //---
    tasks.splice(index, 1)
    res.status(204).send()
});

app.post('/login', (req, res) => {
    const { user, password } = req.body
    if (user === USER && password === PASSWORD) {
        req.session.user = user
        req.session.isAuthenticated = true
        res.status(200).send('logged in successfully')
    } else {
        res.status(401).send('login failed')
    }
})

app.get('/verify', (req, res) => {
    if (!isAuthenticated(req)) {
        return res.status(401).send('user is not authenticated')
    }

    res.send('user is authenticated')
})

app.delete('/logout', (req, res) => {
    if (!isAuthenticated(req)) {
        return res.status(401).send('user is not authenticated')
    }

    req.session.destroy()
    res.status(204).send()
});

//--- Assisted with basic coding tools
app.use((req, res) => {
    res.status(404).send('endpoint not found')
});

app.use((err, req, res, next) => {
    console.error(err.stack);
    res.status(500).send('something broke!')
});
//---

function isTaskStructureCorrect(req, res) {
    const { title, description, done, dueDate } = req.body
    if (!title || !description || done === undefined || !dueDate) {
        console.log(`task structure not right: ${req.body}`)
        res.status(422).send('task structure not right')
        return false
    }
    return true
}

function isAuthenticated(req) {
    console.log(`status of user authentivication: ${req.session.isAuthenticated}`)
    return req.session.isAuthenticated
}

app.listen(port, () => console.log(`Listening on port ${port}`))

export default async (promise, expectedRevertMessage="") => {
  try {
    await promise;
    return
  } catch (error) {
    let invalidOpcode = false;
    let outOfGas = false;
    let revert = false;
    if (expectedRevertMessage !== "") {
      // Check end of error string, it's where the revert reason is output.
      let expectedLen = expectedRevertMessage.length;
      if (expectedLen < error.message.length) {
          // Rather annoyingly, truffle adds a period if it can decode the revert reason.
          if (error.message.search('-- Reason given:') >= 0) {
            revert = expectedRevertMessage === error.message.substring(error.message.length-expectedLen-1, error.message.length-1);
          } else {
            revert = expectedRevertMessage === error.message.substring(error.message.length-expectedLen, error.message.length);
          }
      }
    } else {
      // TODO: Check jump destination to destinguish between a throw
      //       and an actual invalid jump.
      invalidOpcode = error.message.search('invalid opcode') >= 0;
      // TODO: When we contract A calls contract B, and B throws, instead
      //       of an 'invalid jump', we get an 'out of gas' error. How do
      //       we distinguish this from an actual out of gas event? (The
      //       testrpc log actually show an 'invalid jump' event.)
      outOfGas = error.message.search('out of gas') >= 0;
      revert = error.message.search('revert') >= 0;
    }

    assert(
      invalidOpcode || outOfGas || revert,
      'Expected throw with revert string \'' + expectedRevertMessage + '\', got \'' + error + '\' instead',
    );
    return;
  }
  assert.fail('Expected throw not received');
};

import ExpoPixi, { PIXI } from 'expo-pixi';

export default async context => {
  //http://pixijs.io/examples/#/basics/basic.js
  const app = ExpoPixi.application({
    context,
  });
  // const bunny = await ExpoPixi.spriteAsync(require('../../assets/pixi/bunny.png'));

  // Scale mode for all textures, will retain pixelation
  PIXI.settings.SCALE_MODE = PIXI.SCALE_MODES.NEAREST;

  const sprite = PIXI.Sprite.fromImage('required/assets/basics/bunny.png');

  // Set the initial position
  sprite.anchor.set(0.5);
  sprite.x = app.renderer.width / 2;
  sprite.y = app.renderer.height / 2;

  // Opt-in to interactivity
  sprite.interactive = true;

  // Shows hand cursor
  sprite.buttonMode = true;

  // Pointers normalize touch and mouse
  sprite.on('pointerdown', onClick);

  // Alternatively, use the mouse & touch events:
  // sprite.on('click', onClick); // mouse-only
  // sprite.on('tap', onClick); // touch-only

  app.stage.addChild(sprite);

  function onClick() {
    sprite.scale.x *= 1.25;
    sprite.scale.y *= 1.25;
  }
};

