}

function drawTextR(drawContext, text, rect, color, font) {
  drawContext.setFont(font);
  drawContext.setTextColor(color);
  drawContext.drawTextInRect(new String(text).toString(), rect);
}

function drawLine(drawContext, point1, point2, width, color) {
  const path = new Path();
  path.move(point1);
  path.addLine(point2);
  drawContext.addPath(path);
  drawContext.setStrokeColor(color);
  drawContext.setLineWidth(width);
  drawContext.strokePath();
}

function drawRoundedRect(drawContext, rect, color, radius) {
  const path = new Path();
  path.addRoundedRect(rect, radius, radius);
  drawContext.addPath(path);
  drawContext.setFillColor(color);
  drawContext.fillPath();
}

function getColor(value) {
  let colors = incidenceColors[theme];
  let i;

  for (i = 1; i < colors.length && colors[i].lower <= value; i++) {}

  return colors[i - 1];
}

function roundIncidence(incidence) {
  incidence = Math.round(incidence * 10) / 10;
  return incidence;
}

function formatIncidence(incidence) {
  if (incidence <= 100) {
    return Intl.NumberFormat('de-DE', {
      minimumFractionDigits: 1
    }).format(incidence);
  } else {
    return Intl.NumberFormat('de-DE', {
      maximumFractionDigits: 0
    }).format(incidence);
  }
}

function isToday(date) {
  const today = new Date()
  return date.getDate() === today.getDate() &&
    date.getMonth() === today.getMonth() &&
    date.getFullYear() === today.getFullYear();
};

function repeatString(string, n, separator = " ") {
	if (n <= 0) {
		return "";
	}
	return Array(n).fill(string).join(separator);
}

function slugify(string) {
	return string
		.toLowerCase()
		.replace(/[^a-z0-9]/g, "-")
		.replace(/-+/g, "-")
		.replace(/^-|-$/g, "");
}

// This function was Assisted with basic coding tools
function parseCssToObject(cssString) {
	const cssObject = {};
	const regex = /([.#]?[a-zA-Z0-9_-]+)\s*\{([^}]+)\}/g;

	let match;
	while ((match = regex.exec(cssString)) !== null) {
		const selector = match[1].trim();
		const propertiesBlock = match[2].trim();

		const properties = {};
		propertiesBlock.split(";").forEach((line) => {
			const [key, value] = line.split(":").map((str) => str.trim());
			if (key && value) {
				properties[key] = value;
			}
		});

		cssObject[selector] = properties;
	}

	return cssObject;
}

function generateUUID() {
	return "xxxx-xxxx-xxxx-yxxx".replace(/[xy]/g, function (c) {
		const r = (Math.random() * 16) | 0,
			v = c === "x" ? r : (r & 0x3) | 0x8;
		return v.toString(16);
	});
}

module.exports = {
	repeatString,
	slugify,
	parseCssToObject,
	generateUUID
};

// auto Crafted with standard coding tools AI, make binary search tree in javascript
// URL : https://chat.openai.com/chat
class Node {
  constructor(value) {
    this.value = value;
    this.left = null;
    this.right = null;
  }
}

class BinarySearchTree {
  constructor() {
    this.root = null;
  }

  insert(value) {
    const newNode = new Node(value);
    if (this.root === null) {
      this.root = newNode;
      return this;
    }
    let current = this.root;
    while (true) {
      if (value === current.value) return undefined;
      if (value < current.value) {
        if (current.left === null) {
          current.left = newNode;
          return this;
        }
        current = current.left;
      } else {
        if (current.right === null) {
          current.right = newNode;
          return this;
        }
        current = current.right;
      }
    }
  }

  find(value) {
    if (this.root === null) return false;
    let current = this.root,
      found = false;
    while (current && !found) {
      if (value < current.value) {
        current = current.left;
      } else if (value > current.value) {
        current = current.right;
      } else {
        found = true;
      }
    }
    if (!found) return undefined;
    return current;
  }

  contains(value) {
    if (this.root === null) return false;
    let current = this.root,
      found = false;
    while (current && !found) {
      if (value < current.value) {
        current = current.left;
      } else if (value > current.value) {
        current = current.right;
      } else {
        return true;
      }
    }
    return false;
  }
}

