// Here, we will sync our database, create our application, and export this module so that we can use it in the bin directory, where we will be able to establish a server to listen and handle requests and responses;

// Require environmental variables if we are in development or testing;
if (process.env.NODE_ENV !== 'production') {
  require('./secrets');
}

// Module dependencies;
const express = require('express');
const path = require('path');
const cookieParser = require('cookie-parser');
const logger = require('morgan');
const helmet = require('helmet');
const compression = require('compression');

// Utilities;
const createLocalDatabase = require('./utilities/createLocalDatabase');
const seedDatabase = require('./utilities/seedDatabase');

// Our database instance;
const db = require('./database');

// Our apiRouter;
const apiRouter = require('./routes/index');

// A helper function to sync our database;
const syncDatabase = () => {
  if (process.env.NODE_ENV === 'production') {
    db.sync();
  }
  else {
    console.log('As a reminder, the forced synchronization option is on');
    db.sync({ force: true })
      .then(() => seedDatabase())
      .catch(err => {
        if (err.name === 'SequelizeConnectionError') {
          createLocalDatabase();
          seedDatabase();
        }
        else {
          console.log(err);
        }
      });
    }
};

// Instantiate our express application;
const app = express();

// A helper function to create our app with configurations and middleware;
const configureApp = () => {
  app.use(helmet());
  app.use(logger('dev'));
  app.use(express.json());
  app.use(express.urlencoded({ extended: false }));
  app.use(compression());
  app.use(cookieParser());

  // Mount our apiRouter;
  app.use('/api', apiRouter);

  // Error handling;
  app.use((req, res, next) => {
    if (path.extname(req.path).length) {
      const err = new Error('Not found');
      err.status = 404;
      next(err);
    }
    else {
      next();
    }
  });

  // More error handling;
  app.use((err, req, res, next) => {
    console.error(err);
    console.error(err.stack);
    res.status(err.status || 500).send(err.message || 'Internal server error.');
  });
};

// Main function declaration;
const bootApp = async () => {
  await syncDatabase();
  await configureApp();
};

// Main function invocation;
bootApp();

// Export our app, so that it can be imported in the www file;
module.exports = app;

// Aided with basic GitHub coding tools
class PaymentServiceMock {
    constructor() {
        this.transactions = [];
        this.successRate = 1; // Default 100% success rate
    }

    reset() {
        this.transactions = [];
        this.successRate = 1;
    }

    setSuccessRate(rate) {
        this.successRate = Math.max(0, Math.min(1, rate));
    }

    async processPayment(amount, details) {
        const success = Math.random() < this.successRate;
        const transaction = {
            id: `TEST_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
            amount,
            details,
            status: success ? 'success' : 'failed',
            timestamp: new Date(),
            provider: details.provider
        };

        this.transactions.push(transaction);

        if (!success) {
            throw new Error('Payment Failed');
        }

        return transaction;
    }

    getTransactionCount() {
        return this.transactions.length;
    }

    getSuccessfulTransactions() {
        return this.transactions.filter(t => t.status === 'success');
    }

    getFailedTransactions() {
        return this.transactions.filter(t => t.status === 'failed');
    }

    getTransactionsByProvider(provider) {
        return this.transactions.filter(t => t.provider === provider);
    }

    async validatePayment(transactionId) {
        const transaction = this.transactions.find(t => t.id === transactionId);
        return transaction ? transaction.status === 'success' : false;
    }

    async refundPayment(transactionId, amount) {
        const transaction = this.transactions.find(t => t.id === transactionId);
        if (!transaction) {
            throw new Error('Transaction not found');
        }

        const refund = {
            ...transaction,
            id: `REFUND_${transaction.id}`,
            originalTransactionId: transaction.id,
            amount: amount || transaction.amount,
            status: 'refunded',
            timestamp: new Date()
        };

        this.transactions.push(refund);
        return refund;
    }

    async getPaymentMethods() {
        return [
            { id: 'mtn', name: 'MTN Mobile Money', enabled: true },
            { id: 'orange', name: 'Orange Money', enabled: true }
        ];
    }

    getLastTransaction() {
        return this.transactions[this.transactions.length - 1] || null;
    }
}

module.exports = new PaymentServiceMock();

// Forward Azure Monitor Logs to Syslog (via Event Hub)
// Developed as a sample for testing purpuses
// https://github.com/miguelangelopereira/azuremonitor2syslog
// miguelp@microsoft.com

module.exports = function (context, myEventHubMessage) {
    context.log(`JavaScript eventhub trigger function called for message array ${myEventHubMessage}`);
    // initializing syslog
    try{
        var syslog = require("syslog-client");
    } catch (e) {
        throw e;
    }    


    // getting environment variables
    var SYSLOG_SERVER = GetEnvironmentVariable("SYSLOG_SERVER");
    var SYSLOG_PROTOCOL;
    if (GetEnvironmentVariable("SYSLOG_PROTOCOL")=="TCP") {
        SYSLOG_PROTOCOL = syslog.Transport.Tcp;
    } else {
        SYSLOG_PROTOCOL = syslog.Transport.Udp;
    }

    var SYSLOG_HOSTNAME;
    if (GetEnvironmentVariable("SYSLOG_HOSTNAME")==null) {
        SYSLOG_HOSTNAME = "azurefunction"
    } else {
        SYSLOG_HOSTNAME = GetEnvironmentVariable("SYSLOG_HOSTNAME");
    }

    var SYSLOG_PORT = GetEnvironmentVariable("SYSLOG_PORT");

    var SYSLOG_FACILITY;
    if (GetEnvironmentVariable("SYSLOG_FACILITY")==null) {
        SYSLOG_FACILITY = syslog.Facility.Local0;
    } else {
        SYSLOG_FACILITY = GetEnvironmentVariable("SYSLOG_FACILITY");
    }

    // options for syslog connection
    var options = {
        syslogHostname: SYSLOG_HOSTNAME,
        transport: SYSLOG_PROTOCOL,    
        port: SYSLOG_PORT,
        facility: SYSLOG_FACILITY
    };

    // log connection variables
    context.log('SYSLOG Server: ', SYSLOG_SERVER);
    context.log('SYSLOG Port: ', SYSLOG_PORT);
    context.log('SYSLOG Protocol: ', SYSLOG_PROTOCOL);
    context.log('SYSLOG Hostname: ', SYSLOG_HOSTNAME);
    context.log('SYSLOG Facility: ', SYSLOG_FACILITY);

    if ((SYSLOG_SERVER == null) || (SYSLOG_PORT == null) || (SYSLOG_PROTOCOL == null) || (SYSLOG_HOSTNAME == null)) {
        throw "Please setup environment variables. "
    }

    // log received message from event hub
    context.log(`Event Hubs trigger function processed message:  ${myEventHubMessage}`);
    context.log('EnqueuedTimeUtc =', context.bindingData.enqueuedTimeUtc);
    context.log('SequenceNumber =', context.bindingData.sequenceNumber);
    context.log('Offset =', context.bindingData.offset);

    // create syslog client
    var client = syslog.createClient(SYSLOG_SERVER, options);

    // cycle through eventhub messages and send syslog
    myEventHubMessage.forEach((message, index)=>{
        if(typeof message === 'object'){

            var msg = JSON.parse(JSON.stringify(message));
            msg.records.forEach((m1, i) => {
                client.log(JSON.stringify(m1), options, function(error) {        
                    if (error) {
                        context.log("error sending message");
                        context.log(error);
                    } else {
                        context.log("sent message successfully");
                    }
                });
            });

        }
    });


      context.log("completed sending all messages");

    context.done();
};

function GetEnvironmentVariable(name)
{
    return process.env[name];
}

