            // Display when the backup was created
            .addField("Created at", formatedDate, false)
            .setColor("RED");
          message.channel.send(embed);
        })
        .catch((err) => {
          // if the backup wasn't found
          return message.channel.send(
            ":x: | No backup found for `" + backupID + "`!"
