// AUTHOR: Gyandeep Mehra
// JavaScript Concept: 20 Javascript One liners every coder should know
// GITHUB: https://github.com/theGDM

//Hello everyone this is theGDM, here i am going to show you 20 Javascripts one liners that will make your
//life easier.

//1. Check if number is even or odd
const isEven = num => num % 2 === 0;
console.log(isEven(2));
//Result: True

//2. Find average of numbers
const averages = (...nums) => nums.reduce((a, b) => a + b) / nums.length;
averages(1, 2, 3, 4);
//Result: 2.5

//3. Finding Max value
let grades = [89, 96, 58, 77, 62, 93, 81, 99, 73];
const topScore = grades.reduce((max, currVal) => (Math.max(max, currVal))); topScore;
//Result: 99

//4. Generate random number between given interval(inclusive)
const randomNum = (a, b) => Math.floor(Math.random() * (b - a + 1)) + a;
randomNum(20, 22);
//Result: 20

//5. Generate random Hex color
const randomHex = () => `#${Math.floor(Math.random() * 0xffffff).toString(16).padEnd(6, "0")}`;
console.log(randomHex());
// Result: #92b008

//6. Remove dupilicates from array
const removeDuplicates = (arr) => [...new Set(arr)];
console.log(removeDuplicates([1, 2, 3, 3, 4, 4, 5, 5, 6]));
// Result: [ 1, 2, 3, 4, 5, 6 ]

//7. Reverse a string
const reverse = str => str.split('').reverse().join('');
reverse('hello theGDM');     
// Result: 'MDGeht olleh'

//8. Capitalize a string
const capitalize = str => str[0].toUpperCase() + str.substr(1, str.length);
capitalize('theGDM');     
// Result: 'TheGDM'

//9. Scroll to top
const goToTop = () => window.scrollTo(0, 0);
goToTop();

//10. Check if array is empty
const isNotEmpty = arr => Array.isArray(arr) && arr.length > 0;
isNotEmpty([1, 2, 3]);
// Result: true

//11. Shuffle an array
const shuffleArray = (arr) => arr.sort(() => 0.5 - Math.random());
console.log(shuffleArray([1, 2, 3, 4]));
// Result: [ 1, 4, 3, 2 ]

//12. Get the text that user has selected
const getSelectedText = () => window.getSelection().toString();
getSelectedText();

//13. Clear all the cookies stored in the webpage
const clearCookies = document.cookie.split(';').forEach(cookie => document.cookie = cookie.replace(/^ +/, '').replace(/=.*/, `=;expires=${new Date(0).toUTCString()};path=/`));

//14. Check if date is valid
const isDateValid = (...val) => !Number.isNaN(new Date(...val).valueOf());
isDateValid("October 18, 2021 03:24:00");
// Result: true

//15. Easily copy any text to clipboard
const copyToClipboard = (text) => navigator.clipboard.writeText(text);
copyToClipboard("Hello theGDM");

//16. Convert RGB to Hex
const rgbToHex = (r, g, b) =>"#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
rgbToHex(0, 51, 255); 
// Result: #0033ff

//17. Log time from the date in the format hour::minutes::seconds
const timeFromDate = date => date.toTimeString().slice(0, 8);
console.log(timeFromDate(new Date(2021, 0, 10, 17, 30, 0))); 
// Result: "17:30:00"

//18. Find the day of the year
const dayOfYear = (date) => Math.floor((date - new Date(date.getFullYear(), 0, 0)) / 1000 / 60 / 60 / 24);
dayOfYear(new Date());
// Result: 272

//19. Get value of browser cookie
const cookie = name => `; ${document.cookie}`.split(`; ${name}=`).pop().split(';').shift();
cookie('_ga');
// Result: "GA1.2.1929736587.1601974046"

//20. Detect dark-mode
const isDarkMode = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches
console.log(isDarkMode)
// Result: True or False

//Assisted with basic coding tools
$(document).ready(function() {
    // Define the image order and captions
    var images = [
        'ipad.png',
        'sun.png',
        'appalachia.png',
        'appalachia.png', // Duplicate entry for Appalachia
        'cat-meme.png',
        'cat-meme.png',   // Duplicate entry for Cat Meme
        'ohio.png',
        'ohio.png',       // Duplicate entry for Ohio
        'pavement.png',
        'eclipse.png',
        'roots.png'
    ];

    var captions = [
        'I - iPad',
        'S - Sun',
        'A - Appalachia',
        'A x2 - Appalachia',
        'C - Cat Meme',
        'C x2 - Cat Meme',
        'O - Ohio',
        'O x2 - Ohio',
        'P - Pavement',
        'E - Eclipse',
        'R - Roots'
    ];

    var currentIndex = 0;

    // Function to update the image and caption
    function updateImage() {
        $('#slideshow-image').fadeOut(300, function() {
            $(this).attr('src', 'images/' + images[currentIndex]).fadeIn(300);
        });
        $('#caption').text(captions[currentIndex]);
    }

    // Event handler for the 'Previous' button
    $('#prev-btn').click(function() {
        currentIndex = (currentIndex > 0) ? currentIndex - 1 : images.length - 1;
        updateImage();
    });

    // Event handler for the 'Next' button
    $('#next-btn').click(function() {
        currentIndex = (currentIndex < images.length - 1) ? currentIndex + 1 : 0;
        updateImage();
    });
});

import React from "react";
import "./index.css";
import PropTypes from "prop-types";

export default class Wheel extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      selectedItem: null,
      items: [],
    };
    this.selectItem = this.selectItem.bind(this);
  }

  componentDidMount() {
    fetch("http://localhost:5001/projects")
      .then(response => response.json())
      .then(data => {
        this.setState({ items: data });
      })
      .catch(error => {
        console.error("Error fetching items:", error);
      });
  }

  selectItem() {
    if (this.state.items.length === 0 || this.props.spinning === true) {
      console.log("Cant spin empty wheel");
      return;
    }
    if (this.state.selectedItem === null) {
      const selectedItem = Math.floor(Math.random() * this.state.items.length);
      this.props.onChange(selectedItem);
      if (this.props.onSelectItem) {
        this.props.onSelectItem(selectedItem);
      }
      this.setState({ selectedItem });
    } else {
      this.setState({ selectedItem: null });
      setTimeout(this.selectItem, 500);
    }
  }

  render() {
    const { selectedItem, items } = this.state;

    const wheelVars = {
      "--nb-item": items.length,
      "--selected-item": selectedItem,
    };
    const spinning = selectedItem !== null ? "spinning" : "";

    let spinDuration = localStorage.getItem("duration");

    let cssProperties = {};

    cssProperties["--spinning-duration"] = `${spinDuration}s`;
    cssProperties["--wheel-color"] = `${this.props.wheelColor}`;
    cssProperties["--neutral-color"] = `${this.props.fontColor}`;

    if (cssProperties["--wheel-color"] === "null")
      cssProperties["--wheel-color"] = "#d38c12";

    if (cssProperties["--neutral-color"] === "null")
      cssProperties["--neutral-color"] = "#FFFFFF";

    return (
      <div style={cssProperties}>
        <div className="wheel-container">
          <div
            lg={true}
            className={`wheel ${spinning}`}
            style={wheelVars}
            onClick={this.selectItem}
          >
            {items.map((item, index) => (
              <div
                className="wheel-item"
                key={index}
                style={{ "--item-nb": index }}
              >
                {index % 4 === 0 && 'Spin the wheel'}
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }
}

// Define prop types
Wheel.propTypes = { 
  onChange: PropTypes.func.isRequired,
  onSelectItem: PropTypes.func,
  spinning: PropTypes.bool,
  wheelColor: PropTypes.string,
  fontColor: PropTypes.string,
};

// Define default prop values
Wheel.defaultProps = {
  onChange: () => {},
  spinning: false,
  wheelColor: "#d38c12",
  fontColor: "#FFFFFF",
};

