    }],

    // disallow use of multiple spaces
    'no-multi-spaces': ['error', {
      ignoreEOLComments: false,
    }],

    // disallow use of multiline strings
    'no-multi-str': 'error',

    // disallow use of new operator when not part of the assignment or comparison
    'no-new': 'error',

    // disallow use of new operator for Function object
    'no-new-func': 'error',

    // disallows creating new instances of String, Number, and Boolean
    'no-new-wrappers': 'error',

    // disallow use of (old style) octal literals
    'no-octal': 'error',

    // disallow use of octal escape sequences in string literals, such as
    // var foo = 'Copyright \251';
    'no-octal-escape': 'error',

    // disallow reassignment of function parameters
    // disallow parameter object manipulation except for specific exclusions
    // rule: https://eslint.org/docs/rules/no-param-reassign.html
    'no-param-reassign': ['error', {
      props: true,
      ignorePropertyModificationsFor: [
        'acc', // for reduce accumulators
        'accumulator', // for reduce accumulators
        'e', // for e.returnvalue
        'ctx', // for Koa routing
        'req', // for Express requests
        'request', // for Express requests
        'res', // for Express responses
        'response', // for Express responses
        '$scope', // for Angular 1 scopes
      ]
    }],

    // disallow usage of __proto__ property
    'no-proto': 'error',

    // disallow declaring the same variable more then once
    'no-redeclare': 'error',

    // disallow certain object properties
    // https://eslint.org/docs/rules/no-restricted-properties
    'no-restricted-properties': ['error', {
      object: 'arguments',
      property: 'callee',
      message: 'arguments.callee is deprecated',
    }, {
      object: 'global',
      property: 'isFinite',
      message: 'Please use Number.isFinite instead',
    }, {
      object: 'self',
      property: 'isFinite',
      message: 'Please use Number.isFinite instead',
    }, {
      object: 'window',
      property: 'isFinite',
      message: 'Please use Number.isFinite instead',
    }, {
      object: 'global',
      property: 'isNaN',
      message: 'Please use Number.isNaN instead',
    }, {
      object: 'self',
      property: 'isNaN',
      message: 'Please use Number.isNaN instead',
    }, {
      object: 'window',
      property: 'isNaN',
      message: 'Please use Number.isNaN instead',
    }, {
      property: '__defineGetter__',
      message: 'Please use Object.defineProperty instead.',
    }, {
      property: '__defineSetter__',
      message: 'Please use Object.defineProperty instead.',
    }, {
      object: 'Math',
      property: 'pow',
      message: 'Use the exponentiation operator (**) instead.',
    }],

    // disallow use of assignment in return statement
    'no-return-assign': ['error', 'always'],

    // disallow redundant `return await`
    'no-return-await': 'error',

    // disallow use of `javascript:` urls.
    'no-script-url': 'error',

    // disallow self assignment
    // https://eslint.org/docs/rules/no-self-assign
    'no-self-assign': 'error',

    // disallow comparisons where both sides are exactly the same
    'no-self-compare': 'error',

    // disallow use of comma operator
    'no-sequences': 'error',

    // restrict what can be thrown as an exception
    'no-throw-literal': 'error',

    // disallow unmodified conditions of loops
    // https://eslint.org/docs/rules/no-unmodified-loop-condition
    'no-unmodified-loop-condition': 'off',

    // disallow usage of expressions in statement position
    'no-unused-expressions': ['error', {
      allowShortCircuit: false,
      allowTernary: false,
      allowTaggedTemplates: false,
    }],

    // disallow unused labels
    // https://eslint.org/docs/rules/no-unused-labels
    'no-unused-labels': 'error',

    // disallow unnecessary .call() and .apply()
    'no-useless-call': 'off',

    // disallow useless string concatenation
    // https://eslint.org/docs/rules/no-useless-concat
    'no-useless-concat': 'error',

    // disallow unnecessary string escaping
    // https://eslint.org/docs/rules/no-useless-escape
    'no-useless-escape': 'error',

    // disallow redundant return; keywords
    // https://eslint.org/docs/rules/no-useless-return
    'no-useless-return': 'error',

    // disallow use of void operator
    // https://eslint.org/docs/rules/no-void
    'no-void': 'error',

    // disallow usage of configurable warning terms in comments: e.g. todo
    'no-warning-comments': ['off', { terms: ['todo', 'fixme', 'xxx'], location: 'start' }],

    // disallow use of the with statement
    'no-with': 'error',

    // require using Error objects as Promise rejection reasons
    // https://eslint.org/docs/rules/prefer-promise-reject-errors
    'prefer-promise-reject-errors': ['error', { allowEmptyReject: true }],

    // require use of the second argument for parseInt()
    radix: 'error',

    // require `await` in `async function` (note: this is a horrible rule that should never be used)
    // https://eslint.org/docs/rules/require-await
    'require-await': 'off',

    // requires to declare all vars on top of their containing scope
    'vars-on-top': 'error',

    // require immediate function invocation to be wrapped in parentheses
    // https://eslint.org/docs/rules/wrap-iife.html
    'wrap-iife': ['error', 'outside', { functionPrototypeMethods: false }],

    // require or disallow Yoda conditions
    yoda: 'error'
  }
};

// Aided with basic GitHub coding tools
import React, { useState, useEffect } from "react";
import {
  getAllBooks,
  updateProgress,
  deleteBook,
  addBook,
} from "../services/bookService";
import BookCard from "../components/BookCard";

const HomePage = () => {
  // 状態管理
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // 書籍追加モーダル用の状態
  const [showAddModal, setShowAddModal] = useState(false);
  const [formData, setFormData] = useState({
    title: "",
    author: "",
    totalPages: 0,
    currentPage: 0,
    memo: "",
  });
  const [formErrors, setFormErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [addSuccess, setAddSuccess] = useState("");
  // 書籍データを読み込む
  useEffect(() => {
    const loadBooks = async () => {
      setLoading(true);
      try {
        const result = await getAllBooks();
        if (result.success) {
          setBooks(result.books);
          setError("");
        } else {
          console.error("書籍データの読み込みエラー:", result.message);
          setBooks([]);
          setError(result.message);
        }
      } catch (err) {
        console.error("書籍データの読み込み例外:", err);
        setBooks([]);
        setError("データの読み込み中にエラーが発生しました");
      } finally {
        setLoading(false);
      }
    };

    loadBooks();
  }, []);
  // 書籍を削除する関数
  const handleDeleteBook = async (id) => {
    // 確認ダイアログを表示
    if (window.confirm("この書籍を削除してもよろしいですか？")) {
      try {
        const result = await deleteBook(id);
        if (result.success) {
          // 画面上の書籍リストを更新
          setBooks(books.filter((book) => book.id !== id));
        } else {
          alert(result.message);
        }
      } catch (err) {
        console.error("書籍削除エラー:", err);
        alert("書籍の削除中にエラーが発生しました");
      }
    }
  };

  // 読書進捗を更新する関数
  const handleUpdateProgress = async (id, newPage) => {
    // 数値以外の入力は無視
    const pageNumber = parseInt(newPage, 10);
    if (isNaN(pageNumber)) return;

    try {
      // サービスを使用して更新
      const result = await updateProgress(id, pageNumber);

      if (result.success) {
        // 書籍リストを更新
        setBooks((prevBooks) =>
          prevBooks.map((book) => (book.id === id ? result.book : book))
        );
        // 結果を返す（BookCardコンポーネントが使用）
        return result;
      } else {
        alert(result.message);
        return { success: false };
      }
    } catch (err) {
      console.error("進捗更新エラー:", err);
      alert("進捗の更新中にエラーが発生しました");
      return { success: false };
    }
  };

  // 書籍リスト（フィルタリングなし）
  const filteredBooks = books;

  // プラスボタンの処理（総ページ数）
  const handleIncrementTotalPages = () => {
    const currentValue =
      formData.totalPages === "" || formData.totalPages === 0
        ? 0
        : parseInt(formData.totalPages, 10);
    const newValue = currentValue + 1;
    setFormData({
      ...formData,
      totalPages: newValue,
    });
  };

  // マイナスボタンの処理（総ページ数）
  const handleDecrementTotalPages = () => {
    const currentValue =
      formData.totalPages === "" || formData.totalPages === 0
        ? 0
        : parseInt(formData.totalPages, 10);
    // 1より小さくならないようにする
    const newValue = Math.max(1, currentValue - 1);
    setFormData({
      ...formData,
      totalPages: newValue,
    });
  };

  // プラスボタンの処理（現在のページ）
  const handleIncrementCurrentPage = () => {
    const currentValue =
      formData.currentPage === "" || formData.currentPage === 0
        ? 0
        : parseInt(formData.currentPage, 10);
    const totalPages =
      formData.totalPages === "" || formData.totalPages === 0
        ? 0
        : parseInt(formData.totalPages, 10);
    // 総ページ数より大きくならないようにする
    const newValue = Math.min(currentValue + 1, totalPages);
    setFormData({
      ...formData,
      currentPage: newValue,
    });
  };

  // マイナスボタンの処理（現在のページ）
  const handleDecrementCurrentPage = () => {
    const currentValue =
      formData.currentPage === "" || formData.currentPage === 0
        ? 0
        : parseInt(formData.currentPage, 10);
    // 0より小さくならないようにする
    const newValue = Math.max(0, currentValue - 1);
    setFormData({
      ...formData,
      currentPage: newValue,
    });
  };

  // フォーム入力変更ハンドラー
  const handleInputChange = (e) => {
    const { name, value } = e.target;

    let processedValue = value;

    if (name === "totalPages" || name === "currentPage") {
      // 空文字列の場合はそのまま（削除操作を許可するため）
      if (value === "") {
        processedValue = 0;
      } else {
        // 数値以外の文字を除去
        const numericValue = value.replace(/[^\d]/g, "");

        // 数値に変換
        processedValue = numericValue ? parseInt(numericValue, 10) : 0;
      }
    }

    setFormData({
      ...formData,
      [name]: processedValue,
    });
  };

  // フォーム送信ハンドラー
  const handleSubmit = async (e) => {
    e.preventDefault();

    // バリデーション
    const newErrors = {};
    if (!formData.title.trim()) {
      newErrors.title = "タイトルは必須です";
    }

    // 著者名の入力は任意に変更
    // if (!formData.author.trim()) {
    //   newErrors.author = "著者名は必須です";
    // }

    if (formData.totalPages <= 0) {
      newErrors.totalPages = "有効なページ数を入力してください";
    }

    if (formData.currentPage < 0) {
      newErrors.currentPage = "現在のページは0以上である必要があります";
    }

    if (formData.currentPage > formData.totalPages) {
      newErrors.currentPage =
        "現在のページは総ページ数を超えることはできません";
    }

    // エラーがあれば更新して関数を終了
    if (Object.keys(newErrors).length > 0) {
      setFormErrors(newErrors);
      return;
    }

    // エラーをリセット
    setFormErrors({});
    setIsSubmitting(true);

    try {
      // BookServiceを使用して書籍を追加（非同期処理）
      const result = await addBook(formData);

      if (result.success) {
        // 成功メッセージを表示
        setAddSuccess("書籍が追加されました！");

        // 書籍リストを更新
        const updatedResult = await getAllBooks();
        if (updatedResult.success) {
          setBooks(updatedResult.books);
        }

        // フォームをリセット
        setFormData({
          title: "",
          author: "",
          totalPages: 0,
          currentPage: 0,
          memo: "",
        });

        // モーダルを閉じる（2秒後）
        setTimeout(() => {
          setShowAddModal(false);
          setAddSuccess("");
        }, 2000);
      } else {
        // エラーメッセージを表示
        setFormErrors({
          submit:
            result.message ||
            "データの保存中にエラーが発生しました。もう一度お試しください。",
        });
      }
    } catch (error) {
      console.error("書籍追加エラー:", error);
      setFormErrors({
        submit: "エラーが発生しました。ネットワーク接続を確認してください。",
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  // モーダルの外側クリックでモーダルを閉じる
  const handleOutsideClick = (e) => {
    if (e.target.className === "add-book-modal-overlay") {
      setShowAddModal(false);
    }
  };

  // 書籍追加モーダルをレンダリング
  const renderAddBookModal = () => (
    <div className="add-book-modal-overlay" onClick={handleOutsideClick}>
      <div className="add-book-modal">
        <button
          className="close-modal-btn"
          onClick={() => setShowAddModal(false)}
        >
          ×
        </button>

        <h2>新しい書籍を追加</h2>

        {addSuccess && <div className="success-message">{addSuccess}</div>}
        {formErrors.submit && (
          <div className="error-message">{formErrors.submit}</div>
        )}

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="title">
              タイトル <span className="required">*</span>
            </label>
            <input
              type="text"
              id="title"
              name="title"
              value={formData.title}
              onChange={handleInputChange}
              className={formErrors.title ? "error" : ""}
              disabled={isSubmitting}
            />
            {formErrors.title && (
              <p className="error-text">{formErrors.title}</p>
            )}
          </div>{" "}
          <div className="form-group">
            <label htmlFor="author">著者</label>
            <input
              type="text"
              id="author"
              name="author"
              value={formData.author}
              onChange={handleInputChange}
              className={formErrors.author ? "error" : ""}
              disabled={isSubmitting}
            />
            {formErrors.author && (
              <p className="error-text">{formErrors.author}</p>
            )}
          </div>
          <div className="form-group">
            <label htmlFor="totalPages">
              総ページ数 <span className="required">*</span>
            </label>
            <div className="progress-input">
              <button
                type="button"
                className="page-control-btn page-decrement-btn"
                onClick={handleDecrementTotalPages}
                disabled={
                  !formData.totalPages ||
                  formData.totalPages <= 1 ||
                  isSubmitting
                }
              >
                －
              </button>
              <input
                type="text"
                id="totalPages"
                name="totalPages"
                value={formData.totalPages}
                onChange={handleInputChange}
                inputMode="numeric"
                className={formErrors.totalPages ? "error" : ""}
                disabled={isSubmitting}
                placeholder="0"
              />
              <button
                type="button"
                className="page-control-btn page-increment-btn"
                onClick={handleIncrementTotalPages}
                disabled={isSubmitting}
              >
                ＋
              </button>
            </div>
            {formErrors.totalPages && (
              <p className="error-text">{formErrors.totalPages}</p>
            )}
          </div>
          <div className="form-group">
            <label htmlFor="currentPage">現在のページ</label>
            <div className="progress-input">
              <button
                type="button"
                className="page-control-btn page-decrement-btn"
                onClick={handleDecrementCurrentPage}
                disabled={
                  !formData.currentPage ||
                  formData.currentPage <= 0 ||
                  isSubmitting
                }
              >
                －
              </button>
              <input
                type="text"
                id="currentPage"
                name="currentPage"
                value={formData.currentPage}
                onChange={handleInputChange}
                inputMode="numeric"
                className={formErrors.currentPage ? "error" : ""}
                disabled={isSubmitting}
                placeholder="0"
              />
              <button
                type="button"
                className="page-control-btn page-increment-btn"
                onClick={handleIncrementCurrentPage}
                disabled={
                  !formData.totalPages ||
                  (formData.currentPage !== 0 &&
                    formData.currentPage >= formData.totalPages) ||
                  isSubmitting
                }
              >
                ＋
              </button>
              {formData.totalPages > 0 && <span>/ {formData.totalPages}</span>}
            </div>
            {formErrors.currentPage && (
              <p className="error-text">{formErrors.currentPage}</p>
            )}
          </div>
          <div className="form-group">
            <label htmlFor="memo">メモ（任意）</label>
            <textarea
              id="memo"
              name="memo"
              value={formData.memo}
              onChange={handleInputChange}
              rows="3"
              disabled={isSubmitting}
            />
          </div>
          <div className="form-actions">
            <button type="submit" className="btn" disabled={isSubmitting}>
              {isSubmitting ? "追加中..." : "書籍を追加"}
            </button>
            <button
              type="button"
              className="btn btn-secondary"
              onClick={() => setShowAddModal(false)}
              disabled={isSubmitting}
            >
              キャンセル
            </button>
          </div>
        </form>
      </div>
    </div>
  );

  return (
    <div>
      <h2 className="page-title">書籍リスト</h2> {/* 追加ボタン */}
      <div className="book-list-actions">
        <button
          className="btn add-book-btn"
          onClick={() => setShowAddModal(true)}
        >
          + 新しい書籍を追加
        </button>
      </div>
      {loading ? (
        <p className="loading-message">読み込み中...</p>
      ) : error ? (
        <div className="error-state">
          <p className="error-message">{error}</p>
          <button className="btn" onClick={() => window.location.reload()}>
            再読み込み
          </button>
        </div>
      ) : filteredBooks.length > 0 ? (
        <div className="books-grid">
          {filteredBooks.map((book) => (
            <BookCard
              key={book.id}
              book={book}
              onUpdateProgress={handleUpdateProgress}
              onDelete={handleDeleteBook}
            />
          ))}
        </div>
      ) : (
        <div className="empty-state">
          <h3>書籍がありません</h3>
          <p>新しい書籍を追加してみましょう！</p>
          <button className="btn" onClick={() => setShowAddModal(true)}>
            書籍を追加
          </button>
        </div>
      )}
      {/* 書籍追加モーダル */}
      {showAddModal && renderAddBookModal()}
    </div>
  );
};

export default HomePage;

document.addEventListener("DOMContentLoaded", function() {

    // Thanks ChatGPT!
    function MST(d) {
        // Define MST offset (UTC-7 without daylight saving time adjustments)
        const MST_OFFSET = -7;

        // Get the local time offset in hours
        const localOffset = d.getTimezoneOffset() / 60;

        // Calculate the difference between local time and MST
        const offsetDifference = MST_OFFSET - localOffset;

        // Adjust the date to MST
        d.setHours(d.getHours() + offsetDifference);

        return d;
    }

    function getWeekNumber(d) {
        // Copy date so that don't modify the original
        d = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));

        // Set to nearest Thursday: current date + 4 - current day number
        // Make Sunday's day number 7
        d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));

        // Get first day of the year
        var yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));

        // Calculate full weeks to nearest Thursday
        var weekNo = Math.ceil((((d - yearStart) / 86400000) + 1) / 7);

        return weekNo;
    }

    // Get the current date and adjust to MST
    var today = new Date();
    var mstToday = MST(new Date(today.getTime())); // Ensure we are not modifying the original date

    // Calculate the week number and year based on MST
    var weekNumber = getWeekNumber(mstToday);
    var year = mstToday.getFullYear();

    console.log("Week number: " + weekNumber);
    console.log("Year: " + year);

    // Construct the file name for today's mini
    var filename = "connections/CC" + weekNumber + "-" + year;
    var solutionfilename = "solutions/SCC" + (weekNumber-1) + "-" + year;
    console.log(solutionfilename)

    // Create the embeds
    var grid = document.createElement("embed");
    grid.classList.add("connectionsgrid");
    grid.src = filename + ".html";
    var solution = document.createElement("embed");
    solution.classList.add("solutionsgrid");
    solution.src = solutionfilename + ".html";

    // Add everything to the webpage
    document.getElementById("connections").appendChild(grid);
    document.getElementById("solution").appendChild(solution);
});

class CalendarCard extends HTMLElement {
  set hass(hass) {
    if (!this.content) {
      const card = document.createElement('ha-card');
      card.header = this.config.name;
      this.content = document.createElement('div');
      this.content.style.padding = '0 16px 16px';
      card.appendChild(this.content);
      this.appendChild(card);
      moment.locale(hass.language);
    }

    this._hass = hass;

    this
      .getAllEvents(this.config.entities)
      .then(events => this.updateHtmlIfNecessary(events))
      .catch(error => console.log('error', error));
  }

  async getAllEvents(entities) {
    if(!this.lastUpdate || moment().diff(this.lastUpdate, 'minutes') > 15) {
      const start = moment().startOf('day').format("YYYY-MM-DDTHH:mm:ss");
      const end = moment().startOf('day').add(this.config.numberOfDays, 'days').format("YYYY-MM-DDTHH:mm:ss");

      let urls = entities.map(entity => `calendars/${entity}?start=${start}Z&end=${end}Z`);
      let allResults = await this.getAllUrls(urls)
      let events = [].concat
        .apply([], allResults)
        .map(x => this.toEvent(x));

      if(this.config.showProgressBar) {
        if(events.length > 0 && moment().format('DD') === moment(events[0].startDateTime).format('DD')) {
          let now = {startDateTime: moment().format(), type: 'now'}
          events.push(now);
        }
      }

      events.sort((a, b) => new Date(a.startDateTime) - new Date(b.startDateTime));

      let isSomethingChanged = this.isSomethingChanged(events);
      this.events = events;
      this.lastUpdate = moment();
      return { events: events, isSomethingChanged: isSomethingChanged };
    } else {
      return this.events;
    }
  }

  async getAllUrls(urls) {
    try {
      var data = await Promise.all(
        urls.map(
          url => this._hass.callApi('get', url)));
      return (data);
    } catch (error) {
      throw (error);
    }
  }

  updateHtmlIfNecessary(eventList) {
    if(eventList.isSomethingChanged) {
      this.content.innerHTML = `
        <style>
          .day-wrapper {
            border-bottom: 1px solid;
            margin-bottom: 10px;
          }

          .day-wrapper:last-child {
            border-bottom: none;
          }

          .day {
            display: flex;
            flex-direction: row;
            width: 100%;
          }

          .date {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: top;
            flex: 0 1 40px;
          }

          .events {
            flex: 1 1 auto;
          }

          .event-wrapper {
            padding: 5px;
            margin-left: 10px;
          }

          .event {
            flex: 0 1 auto;
            display: flex;
            flex-direction: column;
          }

          .info {
            display: flex;
            width: 100%;
            justify-content: space-between;
            flex-direction: row;
          }

          .congrats {
            cursor: pointer;
          }

          .time {
            font-size: smaller;
            color: var(--primary-color);
          }

          .now {
            color: var(--paper-item-icon-color, #44739e);
          }

          hr.now {
            border-style: solid;
            border-color: var(--primary-color);
            border-width: 1px 0 0 0;
            margin-top: -9px;
            margin-left: 5px;
          }

          ha-icon {
            color: var(--paper-item-icon-color, #44739e);
          }

          ha-icon.now {
            height: 16px;
            width: 16px;
          }

        </style>
      `;

      let events = eventList.events;
      let groupedEventsPerDay = this.groupBy(events, event => moment(event.startDateTime).format('YYYY-MM-DD'));

      groupedEventsPerDay.forEach((events, day) => {
        let eventStateCardContentElement = document.createElement('div');
        eventStateCardContentElement.classList.add('day-wrapper');
        eventStateCardContentElement.innerHTML = this.getDayHtml(day, events);
        this.content.append(eventStateCardContentElement);
      });
    }
  }

  getDayHtml(day, events) {
    let clazz = moment().format('DD') === moment(day).format('DD') ? 'date now' : 'date';
    return `
      <div class="day">
        <div class="${clazz}">
          <div>${moment(day).format('DD')}</div>
          <div>${moment(day).format('ddd')}</div>
        </div>
        <div class="events">${events.map(event => this.getEventHtml(event)).join('')}</div>
      </div>`;
  }

  getEventHtml(event) {
    if(event.type) {
        return `<ha-icon icon="mdi:circle" class="now"></ha-icon><hr class="now" />`;
    }
    //${event.summary.indexOf('birthday') > 0 ? `<div class="congrats"><i class="fas fa-gift"></i>&nbsp;Send congrats</div>` : ''}
    return `
      <div class="event-wrapper">
        <div class="event">
          <div class="info">
            <div class="summary">${event.title}</div>
            ${event.location ? `<div class="location"><ha-icon icon="mdi:map-marker"></ha-icon>&nbsp;
            ${event.locationAddress ? `<a href="https://www.google.com/maps/place/${event.locationAddress}" target="_blank">${event.location}</a></div>` : `${event.location}</div>`}` : ''}
          </div>
          <div class="time">${event.isFullDayEvent ? 'All day' : (moment(event.startDateTime).format('HH:mm') + `-` + moment(event.endDateTime).format('HH:mm'))}</div>
        </div>
      </div>`;
  }

  setConfig(config) {
    if (!config.entities) {
      throw new Error('You need to define at least one calendar entity via entities');
    }
    this.config = {
      name: 'Calendar',
      showProgressBar: true,
      numberOfDays: 7,
      ...config
    };
  }

  // The height of your card. Home Assistant uses this to automatically
  // distribute all cards over the available columns.
  getCardSize() {
    return 3;
  }

  toEvent(anEvent) {
    if(anEvent.htmlLink) {
      return new GoogleCalendarEvent(anEvent);
    }
    return new CalDavCalendarEvent(anEvent);
  }

  isSomethingChanged(events) {
    let isSomethingChanged = JSON.stringify(events) !== JSON.stringify(this.events);
    return isSomethingChanged;
  }

  deepClone(obj) {
    return JSON.parse(JSON.stringify(obj));
  }

  groupBy(list, keyGetter) {
    const map = new Map();
    list.forEach((item) => {
        const key = keyGetter(item);
        const collection = map.get(key);
        if (!collection) {
            map.set(key, [item]);
        } else {
            collection.push(item);
        }
    });
    return map;
  }
}

class GoogleCalendarEvent {
  constructor(googleCalendarEvent) {
    this.googleCalendarEvent = googleCalendarEvent;
  }

  get startDateTime() {
    if (this.googleCalendarEvent.start.date) {
      let dateTime = moment(this.googleCalendarEvent.start.date);
      return dateTime.toISOString();
    }
    return this.googleCalendarEvent.start.dateTime;
  }

  get endDateTime() {
    return this.googleCalendarEvent.end.dateTime;
  }

  get title() {
    return this.googleCalendarEvent.summary;
  }

  get description() {
    return this.googleCalendarEvent.description;
  }

  get location() {
    if(this.googleCalendarEvent.location) {
      return this.googleCalendarEvent.location.split(',')[0]
    }
    return undefined;
  }

  get locationAddress() {
    if(this.googleCalendarEvent.location) {
      let address = this.googleCalendarEvent.location.substring(this.googleCalendarEvent.location.indexOf(',') + 1);
      return address.split(' ').join('+');
    }
    return undefined;
  }

  get isFullDayEvent() {
    return this.googleCalendarEvent.start.date;
  }
}

class CalDavCalendarEvent {
  constructor(calDavCalendarEvent) {
    this.calDavCalendarEvent = calDavCalendarEvent;
  }

  get startDateTime() {
    return this.calDavCalendarEvent.start;
  }

  get endDateTime() {
    return this.calDavCalendarEvent.end;
  }

  get title() {
    return this.calDavCalendarEvent.title;
  }

  get description() {
    return this.calDavCalendarEvent.description;
  }

  get location() {
    if(this.calDavCalendarEvent.location) {
      return this.calDavCalendarEvent.location;
    }
    return undefined;
  }

  get locationAddress() {
    return undefined;
  }

  get isFullDayEvent() {
    let start = moment(this.startDateTime);
    let end = moment(this.endDateTime);
    let diffInHours = end.diff(start, 'hours');
    return diffInHours >= 24;
  }
}

