            const ctx = {
                window: { addEventListener: fnMock },
                document: {
                    addEventListener: fnMock,
                    removeEventListener: fnMock,
                    cookie: this.cookie,
                },
                navigator: { userAgent: this.ua },
            };

            vm.createContext(ctx);
            vm.runInContext(jsContent, ctx);
