document.addEventListener('DOMContentLoaded', () => {

    const notesContainer = document.getElementById('notes-container');

    // CHATGPT: Disable editing for all textareas within notes
    const disableTextAreas = () => {
        const textareas = notesContainer.querySelectorAll('textarea');
        textareas.forEach(textarea => {
            textarea.disabled = true; // Disable editing
        });
    };
    disableTextAreas();


    const hideDeleteButtons = () => {
        const deleteButtons = notesContainer.querySelectorAll('.delete-button');
        deleteButtons.forEach(button => {
            button.style.display = 'none'; // Hide delete buttons
        });
    };
    hideDeleteButtons();


    setInterval(() => {
        noteManager.getNotesFromStorage();
        noteManager.updateNotes(); // Update notes based on localStorage changes
    }, 2000);

    // CHATGPT: Update the notes if the "notes" key in localStorage changes in other tabs
    window.addEventListener('storage', (event) => {
        if (event.key === 'notes') {
            console.log("STORAGE CHANGED")
            noteManager.getNotesFromStorage();
            noteManager.updateNotes(); 
            disableTextAreas();
            hideDeleteButtons();
        }
    });
});

// Aided with basic GitHub coding tools
const User = require('../../models/userModel');
const jwt = require('jsonwebtoken');

class UserFactory {
    static async create(overrides = {}) {
        const defaultData = {
            name: `Test User ${Date.now()}`,
            email: `user${Date.now()}@test.com`,
            matricule: `TST${Date.now()}`,
            password: 'TestPass123!',
            role: 'student',
            status: 'Active'
        };

        if (defaultData.role === 'student' || overrides.role === 'student') {
            defaultData.faculty = 'Engineering';
            defaultData.program = 'Computer Engineering';
        }

        const userData = { ...defaultData, ...overrides };
        const user = await User.create(userData);
        const token = jwt.sign(
            { id: user._id, role: user.role },
            process.env.JWT_SECRET,
            { expiresIn: process.env.JWT_EXPIRES_IN }
        );

        return { user, token };
    }

    static async createStudent(overrides = {}) {
        const defaultData = {
            name: `Test Student ${Date.now()}`,
            email: `student${Date.now()}@test.com`,
            matricule: `STU${Date.now()}`,
            faculty: 'Engineering',
            program: 'Computer Engineering',
            password: 'Password123!',
            role: 'student',
            status: 'Active'
        };

        return await this.create({ ...defaultData, ...overrides });
    }

    static async createAdmin(overrides = {}) {
        const defaultData = {
            name: `Admin ${Date.now()}`,
            email: `admin${Date.now()}@test.com`,
            matricule: `ADM${Date.now()}`,
            password: 'AdminPass123!',
            role: 'admin',
            status: 'Active'
        };

        return await this.create({ ...defaultData, ...overrides });
    }

    static async createHOD(overrides = {}) {
        const defaultData = {
            name: `HOD ${Date.now()}`,
            email: `hod${Date.now()}@test.com`,
            matricule: `HOD${Date.now()}`,
            faculty: 'Engineering',
            program: 'Computer Engineering',
            password: 'HodPass123!',
            role: 'hod',
            status: 'Active'
        };

        return await this.create({ ...defaultData, ...overrides });
    }

    static async createManyStudents(count, overrides = {}) {
        const students = [];
        for (let i = 0; i < count; i++) {
            const student = await this.createStudent(overrides);
            students.push(student);
        }
        return students;
    }
}

module.exports = UserFactory;
